# Edition 2, items batch 2: weapons for the types that had no item, and consumables.
# (name, category, rarity, attunement, text)
A = "Requires Attunement"
ITEMS = [
# ================= WEAPONS =================
("Peacekeeper's Club", "Weapon (Club)", "Common", None, "This polished club makes no sound when it strikes. When you reduce a creature to 0 Hit Points with it, the creature is always knocked out instead of killed, with no choice needed."),
("Homing Darts", "Weapon (Dart)", "Common", None, "This set of six darts has feathers dyed in one bright color. At the end of your turn, each dart you threw this turn that is within 30 feet of you flies back to your hand or your belt."),
("Harvest Moon Sickle", "Weapon (Sickle)", "Uncommon", None, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. Plants you cut with it grow back within a day. Once per dawn, you can cast Entangle (save DC 13) from it."),
("Wasp-Nest Blowgun", "Weapon (Blowgun)", "Uncommon", None, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a creature with it, the creature makes a DC 13 Constitution save. On a failed save, it takes an extra 1d4 Poison damage and can't take Reactions until the start of its next turn."),
("Shortbow of the Fleeting Step", "Weapon (Shortbow)", "Uncommon", A, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. Once on each of your turns, after you make an attack with it, you can move up to 5 feet. This movement doesn't provoke Opportunity Attacks."),
("Axe of the First Snow", "Weapon (Battleaxe)", "Rare", A, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon, and it deals an extra 1d6 Cold damage on a hit. When you score a Critical Hit with it, the target's Speed is 0 until the end of its next turn. Snow never settles on the axe, and you don't suffer the effects of extreme cold while you carry it."),
("Morningstar of the Dawn Bell", "Weapon (Morningstar)", "Rare", A, "You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. Once per dawn, when you hit a creature with it, you can make it ring like a temple bell. Each creature of your choice within 10 feet of the target, and the target itself, makes a DC 15 Constitution save. On a failed save, a creature takes 2d6 Thunder damage and has the Deafened condition for 1 minute."),
("Delver's Pick", "Weapon (War Pick)", "Rare", None, "You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon, and it deals double damage to objects and structures. You can use it to dig through stone at a rate of 5 feet every 10 minutes, or through earth at five times that rate."),
("Sleeve Crossbow", "Weapon (Hand Crossbow)", "Rare", A, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. As a Bonus Action, you can fold it into a flat case no bigger than your hand, or unfold it. While folded, it can be found only with a successful DC 20 Wisdom (Perception) check. Once per dawn, when you hit a creature with it, the creature makes a DC 15 Wisdom save or has the Unconscious condition for 1 minute. The effect ends early if the creature takes damage or someone takes an action to wake it."),
("Pistol of the Sure Shot", "Weapon (Pistol)", "Rare", A, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon, and it ignores the Loading property. Once per dawn, when you miss with an attack roll made with it, you can reroll the attack and must use the new roll."),
("Pike of the Long Wall", "Weapon (Pike)", "Very Rare", A, "You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. When a creature you can see enters your reach, you can take a Reaction to make one attack with the pike against it. If the attack hits, the creature's Speed is 0 until the end of the current turn."),
("Oakheart Greatclub", "Weapon (Greatclub)", "Very Rare", A, "You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a Large or smaller creature with it, the creature makes a DC 17 Strength save or is pushed up to 10 feet away from you and has the Prone condition. Once per dawn, as a Bonus Action, you can make the club grow into a small tree trunk for 1 minute. While it is grown, it has the Reach property and deals an extra 2d6 Bludgeoning damage on a hit."),
("Thunderbark Musket", "Weapon (Musket)", "Very Rare", A, "You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. Attacks you make with it ignore Half Cover and Three-Quarters Cover, and its long range is doubled."),
# ================= POTIONS =================
("Tonic of the Clear Morning", "Potion", "Common", None, "This fizzing green tonic ends the Poisoned condition if alcohol caused it, and it clears a sore head at once. It tastes of mint and regret."),
("Potion of Bright Eyes", "Potion", "Common", None, "For 1 hour after you drink this potion, your eyes shed Dim Light in a 10-foot Cone in the direction you look. You can end the effect early as a Bonus Action."),
("Philter of Small Talk", "Potion", "Common", None, "For 8 hours after you drink this philter, you remember the name, the face, and one small detail of every creature you are introduced to."),
("Potion of Featherweight", "Potion", "Uncommon", None, "For 1 hour after you drink this potion, you fall at a rate of 60 feet per round and take no damage from falling, and your jump distance is tripled."),
("Oil of the Ghost Blade", "Potion", "Uncommon", None, "You can coat one weapon or up to 10 pieces of ammunition with this oil as a Bonus Action. For 1 minute, the weapon or ammunition can hit creatures on the Ethereal Plane, and it deals Force damage instead of its normal damage type."),
("Potion of the Hound's Nose", "Potion", "Uncommon", None, "For 8 hours after you drink this potion, you have Advantage on Wisdom (Perception) and Wisdom (Survival) checks that rely on smell, and you can follow the scent trail of a creature you have smelled in the last day as long as the trail is less than 24 hours old."),
("Potion of Borrowed Tongues", "Potion", "Uncommon", None, "After you drink this potion, choose one language you hear spoken within the next minute. For 1 hour, you can speak, read, and understand that language."),
("Potion of the Adapting Skin", "Potion", "Rare", None, "For 1 hour after you drink this potion, your skin learns from what hurts it. When you take Acid, Cold, Fire, Lightning, or Thunder damage, you can take a Reaction to gain Resistance to that damage type, including against the triggering damage. The Resistance lasts until the potion's effect ends or until you use this Reaction again for a different type."),
("Potion of the Salamander", "Potion", "Rare", None, "For 1 hour after you drink this potion, you have Immunity to Fire damage, and you can walk across molten rock as if it were solid ground. Your touch is warm enough to light a candle."),
("Potion of the Deep Delver", "Potion", "Rare", None, "For 8 hours after you drink this potion, you have Darkvision with a range of 120 feet and Tremorsense with a range of 30 feet, and you can breathe normally in smoke, dust, and foul air."),
("Potion of Renewal", "Potion", "Very Rare", None, "When you drink this potion, you regain 4d8 + 8 Hit Points, and you gain the benefit of the Greater Restoration spell."),
("Draught of the Waking Dream", "Potion", "Legendary", None, "For 8 hours after you drink this draught, you see a moment ahead of the world. You have Advantage on D20 Tests, and other creatures have Disadvantage on attack rolls against you. You can't drink another Draught of the Waking Dream until you finish a Long Rest."),
# ================= SCROLLS =================
("Scroll of the Faithful Copy", "Scroll", "Common", None, "Lay this blank scroll on a page of writing or a drawing and speak the command word. The ink copies itself onto the scroll in 1 minute, exactly, including any mistakes. Magic writing, such as a spell, isn't copied."),
("Scroll of the Walked Road", "Scroll", "Common", None, "When you unroll this scroll, it draws a map of the route you walked during the last hour, with the turns, stairs, and doors you passed. The map stays on the scroll, and the scroll can't be used again."),
("Scroll of the Bonfire", "Scroll", "Uncommon", None, "As a Magic action, you read this scroll and throw it on the ground, where it becomes a warm campfire that burns for 8 hours without fuel. Beasts of CR 1/2 or lower won't willingly come within 30 feet of the fire unless they are attacked. The fire doesn't spread."),
("Scroll of the Sudden Wall", "Scroll", "Uncommon", None, "As a Magic action, you read this scroll and point at an unoccupied space within 30 feet. A wall of thick wood, 10 feet long, 10 feet high, and 1 foot thick, grows there. The wall has AC 12 and 30 Hit Points, and it rots to dust after 10 minutes."),
("Scroll of Turned Fate", "Scroll", "Uncommon", None, "When a creature you can see within 60 feet of you succeeds on an attack roll or a saving throw, you can take a Reaction to read this scroll. The creature rerolls the d20 and must use the lower roll. The scroll then turns to dust."),
("Scroll of the Safe Cottage", "Scroll", "Rare", None, "As a Magic action, you read this scroll aloud. A small stone cottage appears in an unoccupied space within 30 feet and lasts for 8 hours. It has one room, warm beds and a fire for up to eight creatures, and a door that opens only for the creatures you name when you read the scroll. The cottage's walls and door can't be damaged or passed through by any means short of a spell of level 4 or higher."),
("Scroll of the Gathered Host", "Scroll", "Rare", None, "As a Magic action, you read this scroll aloud and name up to six creatures you know well. Each named creature within 1 mile of you hears your voice and can choose to be teleported to an unoccupied space within 30 feet of you. The scroll then turns to dust."),
("Scroll of the Unbroken Circle", "Scroll", "Very Rare", None, "As a Magic action, you read this scroll and choose Aberrations, Celestials, Elementals, Fey, Fiends, or Undead. For 8 hours, a ward fills a 60-foot-radius Emanation from the spot where you stood. Creatures of the chosen type can't willingly enter the ward or teleport into it, and one that is in the ward when it appears is pushed to the nearest space outside it. A creature of the chosen type that is in the ward takes 5d10 Radiant damage at the start of each of its turns."),
# ================= AMMUNITION =================
("Lantern Arrow", "Ammunition", "Common", None, "When this arrow hits a surface or a creature, its head bursts into a soft glow that sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet for 10 minutes. Found in bundles of 1d4 + 2."),
("Smoke Arrow", "Ammunition", "Uncommon", None, "When this arrow hits a surface or a creature, it releases a 15-foot-radius Sphere of thick grey smoke that is Heavily Obscured for 1 minute. A strong wind disperses it. Found in bundles of 1d4."),
("Thunderclap Bullet", "Ammunition", "Uncommon", None, "On a hit, this sling bullet deals an extra 1d6 Thunder damage, and the target makes a DC 13 Constitution save. On a failed save, it has the Deafened condition and can't take Reactions until the end of its next turn. Found in bundles of 1d4 + 1."),
("Seeking Arrow", "Ammunition", "Rare", None, "When you fire this arrow, name a creature you have seen within the last minute. The arrow flies around corners and through gaps to find it, up to the weapon's long range. The attack roll has Advantage, and it ignores all cover except Total Cover. If the creature is out of range, the arrow drops to the ground and isn't used up."),
("Arrow of the Winter Hunt", "Ammunition", "Rare", None, "On a hit, the target takes an extra 3d6 Cold damage, and it makes a DC 15 Constitution save. On a failed save, its Speed is halved for 1 minute. It repeats the save at the end of each of its turns, ending the effect on itself on a success."),
("Bolt of Banishing", "Ammunition", "Very Rare", None, "On a hit, the target makes a DC 17 Charisma save. On a failed save, it vanishes to a harmless pocket of another plane for 1 minute and has the Incapacitated condition there. When the minute ends, it reappears in the space it left or the nearest unoccupied space. The bolt then crumbles."),
("Bullet of the Falling Mountain", "Ammunition", "Very Rare", None, "This heavy bullet can be fired from a sling or a musket. On a hit, the target takes an extra 6d10 Force damage, is pushed up to 20 feet away from you, and has the Prone condition. The bullet then crumbles to sand."),
]
